import type { EntityInput, TechnologyInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";

/**
 * Recovery and rejuvenation, the mind and the life around it: the part of recovery people rate as hardest.
 *
 * Wave one of this front covered the body system by system, hair, and biological ageing. This file is what those
 * records do not reach: fear that the cancer will come back, mood after treatment, traumatic stress, body image and
 * identity, partners, carers and children, work, money, insurance, and sleep. Fear of recurrence did not exist in
 * the corpus before this round and is the problem survivorship research most often names as the commonest unmet
 * need; sleep did not exist either, and the treatment for it has the strongest evidence of anything in this file.
 *
 * Every figure here was read from the abstract or full text of the source cited beside it, and every identifier was
 * resolved through PubMed, Crossref, legislation.gov.uk, the United States Code, the electronic Code of Federal
 * Regulations or GOV.UK before it was used. Where a claim is widely repeated and OnCo could not reach a primary
 * source for it, the record says so instead of printing the number.
 *
 * Each record carries an honest grade as a tag `evidence:<grade>`, the same model as src/data/complementary.ts:
 * strong = consistent randomised trials plus a major guideline recommendation; moderate = trials exist but small,
 * mixed or single-setting; insufficient = no reliable human evidence of benefit; no-benefit = adequately sized
 * trials found nothing; harm = toxicity, interaction, or use in place of standard treatment. The records that
 * describe a law or a word rather than a treatment carry no grade, because there is nothing to grade.
 *
 * Records the corpus already held are supplemented in place rather than duplicated. `psycho-oncology`,
 * `financial-navigation`, `financial-toxicity`, `sleep-circadian-interventions` and `relaxation-guided-imagery`
 * gain the `rejuvenation` front in their own files. `cbt-insomnia-cancer`, `cbt-fatigue-distress`,
 * `mindfulness-based-interventions`, `survivorship-care-plan`, `body-image-after-breast-surgery` and
 * `sexual-function-after-cancer` already carry it and are referenced rather than rewritten.
 * `cognitive-impairment-after-cancer-treatment` belongs to wave one and is linked, not restated.
 *
 * UK spelling. The `rejuvenation` section record itself is defined in src/data/sections.ts.
 */

const asOf = "2026-10-02";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

const REJ = "rejuvenation";
const SUP = "supportive-care";

const T = (grade: EvidenceGrade | null, extra: string[] = []) =>
  grade ? ["rejuvenation", "survivorship", `evidence:${grade}`, ...extra] : ["rejuvenation", "survivorship", ...extra];
const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });

// Sources used by more than one record.
